function transaction(fn){const ok=C.atomic(fn);if(!ok)message=C.takeFailure()||'保存失败，本次行动已撤回。';return ok;}
function days(n,act,ctx={}){const r=advanceDays(n,{act,rate:0,incomeMul:0,...ctx},{stopOnEvent:true});if(r.died){die('寿元耗尽');return false;}if(r.event){startEvent(r.event);return false;}return r.days===n&&G.mode==='idle';}
function notify(text){message=text;render();}
function bind(el=document.getElementById('scene')){el.querySelectorAll('[data-sb]').forEach(b=>b.onclick=()=>S.dispatch(b.dataset.sb,b.dataset.arg));}
function page(title,html){document.body.classList.add('sb-screen');document.getElementById('scene').innerHTML='<section class="sb-shell qi51 qi52"><header class="sb-head"><div><small>'+esc(W.locationLabel())+'</small><h2>'+esc(title)+'</h2></div></header><div class="sb-scroll">'+(message?'<p class="qi-notice51" role="status">'+esc(message)+'</p>':'')+html+'</div></section>';bind();}
function entry(id){const d=state();return d.routes[id]||(d.routes[id]={completed:-1,active:null,history:[]});}
function acquireReason(title){const m=Q.library[title];if(!m?.stage||m.stage===1)return '';if(G.realm===0&&G.layer<m.stage)return '这部'+m.stage+'层篇尚需积累修为；不按灵根封锁。';if(D.routes[m.route52]&&entry(m.route52).completed<(m.stage===4?0:1))return '须先完成「'+D.routes[m.route52].name+'」上一段传习，再购买进阶抄本。';return '';}
function studyReason(title){return level(title)>0?'':acquireReason(title);}
function craftReason(id){const r=recipes[id];if(!r)return '没有这项工艺。';if(G.realm===0&&G.layer<r.stage)return '需要炼气'+r.stage+'层的主持能力。';if(!S.state().recipes.includes(id))return '尚无工艺，须到县中工坊购买工艺录并阅读。';if(r.stage>1&&entry(r.route).completed<(r.stage===4?0:1))return '先完成上一段百艺传习，再开进阶工序。';return '';}
function craftSite(id){return S.workshop(recipes[id]?.type==='alchemy'?'alchemy':'forge');}
function craft(id){const r=recipes[id],why=craftReason(id);if(why)return notify(why);const at=craftSite(id);if(!at)return notify('须到实际炉坊租炉，或在安全工位布置对应工具。');if(at.until&&at.until<S.now()+r.days)return notify('炉位租期不足，请先续租。');if(G.stones<r.fee||Object.entries(r.materials).some(([k,n])=>(G.inventory[k]||0)<n))return notify('灵石或材料不足。');transaction(()=>{if(!days(r.days,'百艺制作'))return;const at=craftSite(id);if(!at||at.until&&at.until<S.now())throw Error('工位失效');stoneChange(G,-r.fee,items[id][0]+'工序');for(const [k,n]of Object.entries(r.materials))G.inventory[k]-=n;const d=state();d.skills[r.type]=Math.min(10,Math.max(d.skills[r.type]||0,S.state().skills[r.type]||0)+1);S.state().skills[r.type]=d.skills[r.type];const expertise=Q.stats().features52?.[r.type]||0,success=Math.random()<Math.min(.97,.82+d.skills[r.type]*.02+(G.attr.wu-5)*.005+expertise*.03);if(success){G.inventory[id]=(G.inventory[id]||0)+1;d.crafted[id]=(d.crafted[id]||0)+1;G.content47||={crafted:{}};G.content47.crafted[id]=(G.content47.crafted[id]||0)+1;message='制成'+items[id][0]+'，可在行囊查看，实际工时与用料已结清。';addLog(message,'up');}else{message=items[id][0]+'制作失手，材料与炉火已耗，技艺有所长进。';addLog(message,'mute');}});render();}
function materialsText(m){const sources={herb:'野外采集／药铺／坊市行商',ironOre:'野外采集／铁匠／坊市顾散人',spiritTimber47:'乡野或山岭采集地「寻青纹灵木」／铁匠',blankPaper52:'县中工坊或道观前院的工艺物资',spiritInk52:'县中工坊或道观前院的工艺物资',arrayStone52:'县中工坊或道观前院的工艺物资'};return Object.entries(m).map(([id,n])=>esc(BAG_ITEMS[id]?.name||id)+' '+(G.inventory[id]||0)+'/'+n+'（'+esc(sources[id]||C.catalog[id]?.source||'当地取得')+'）').join('<br>');}
function supplies(){const ids=['blankPaper52','spiritInk52','arrayStone52','beastFood52',...Object.keys(recipeGroups).map(k=>k+'Patterns52')];return card('工坊纸墨与工艺录','到县城工坊或道观前院购买；材料有每月现货，工艺录买后在行囊阅读。',ids.map(id=>B((items[id]?.[0]||BAG_ITEMS[id].name)+' · '+BAG_ITEMS[id].price+'灵石（持有'+(G.inventory[id]||0)+'）','supply',id,!bench())).join(''));}
function buySupply(id){if(!bench()||!C.catalog[id]||!['blankPaper52','spiritInk52','arrayStone52','beastFood52',...Object.keys(recipeGroups).map(k=>k+'Patterns52')].includes(id))return;const price=BAG_ITEMS[id].price;if(G.stones<price)return notify('灵石不足，需要'+price+'灵石。');const recipesIn=C.catalog[id].recipes;if(recipesIn?.every(k=>S.state().recipes.includes(k)))return notify('工艺录内容已学过，不必再买。');transaction(()=>{const d=state(),key=G.place+'_'+absMonth(),market=d.market[key]||(d.market[key]={stock:{},wallet:0});const stock=market.stock[id]??(recipesIn?3:50);if(stock<=0)throw Error('现货不足');stoneChange(G,-price,'工坊购买'+BAG_ITEMS[id].name);market.stock[id]=stock-1;market.wallet+=price;G.inventory[id]=(G.inventory[id]||0)+1;});render();}
function recipePanel(route){const list=recipeGroups[route]||[];return list.map(id=>{const r=recipes[id],why=craftReason(id);return card(items[id][0],esc(items[id][4])+'<br>炼气'+r.stage+'层工序 · '+r.days+'日 · '+r.fee+'灵石<br>'+materialsText(r.materials)+'<br>'+esc(why||craftSite(id)?.label||'尚无工位'),B('实际制作','craft',id,!!why));}).join('');}
function metrics(active){return active?.metrics||{hits:0,wins:0,uses:0,elements:[],utility:0};}
function deliveryItem(id,step){return id==='forge'?['edgeBlade52','bodyArmor52','ringBlade52'][step]:recipeGroups[id][step];}
function objective(id,step,mode){const r=D.routes[id],target=['rat','wolf','boar'][step];if(['alchemy','forge'].includes(id)){const item=deliveryItem(id,step);return '实际制作'+items[item][0]+'1件，并在县城入口提交实物。';}if(id==='array'&&mode==='utility')return '制作并布置'+items[['gatherArray52','nourishArray52','watchArray52'][step]][0]+'，实际完成对应辅助行动一次，再回来核验。';return '以'+r.name+'的实际行动至少发挥'+(id==='element'?step+1:2)+'次'+(id==='element'?'不同五行术法':'')+'，实战击退'+Q.enemies[target].name+'1次'+(r.craft?'；本段须有实际制作记录。':'')+'。';}
function ready(id){const r=D.routes[id],e=entry(id),a=e.active;if(!a)return false;const m=metrics(a),step=a.step;
 if(['alchemy','forge'].includes(id)){const item=deliveryItem(id,step);return (state().crafted[item]||0)>(a.craftBefore[item]||0)&&(G.inventory[item]||0)>0;}
 if(id==='array'&&a.mode==='utility')return m.utility>0;
 const minHits=id==='element'?m.elements.length>=step+1:m.hits>=2;
 let crafted=true;if(r.craft){const list=id==='array'?Object.keys(arrays).filter(k=>arrays[k].combat):id==='talisman'?[recipeGroups[id][step]]:recipeGroups[id];crafted=list.some(k=>(state().crafted[k]||0)>(a.craftBefore[k]||0));}
 return m.wins>0&&minHits&&crafted;
}
function routePage(id){const r=D.routes[id];if(!r)return overview();const e=entry(id),step=e.active?.step??Math.min(2,e.completed+1),m=metrics(e.active),labels=['入门','进阶','炼气后期'];let html=card(r.name,esc(r.description)+'<br>这是学习方向，可以与其他方向混搭。',B('返回路线总览','open')+A('配功与备招','arts')+A('演练与斗法','hub'));
 html+=card(labels[step]+'传习',e.completed===2&&!e.active?'三段传习均已实际核验完成。':esc(objective(id,step,e.active?.mode))+'<br>要求炼气'+[1,4,8][step]+'层；在眼前传习者处接取，回原经办人处交付。'+(e.active?'<br>经办人：'+esc((W.get(e.active.sourceId)?.name||'原传习者')+(W.alive(W.get(e.active.sourceId))?'':'（已故，可放弃本段证据后另觅传习者）'))+' · '+esc(placeName(e.active.sourcePlace))+'<br>证据：实际发挥 '+m.hits+'；指定实战胜利 '+m.wins+'；五行种类 '+m.elements.length+'；辅助行动 '+m.utility:''),e.active?B('当面核验并交付 · 1日','report',id,!ready(id)||!W.present(e.active.sourceId))+B('放弃本段证据，保留已学','cancel',id):e.completed<2?B('接取本段传习','accept',id,!teacher())+(id==='array'?B('改走本段辅助阵传习','accept',id+':utility',!teacher()):''):'');
 const titles=[...r.minds,...(r.arts||[]),...Object.entries(D.library).filter(([,m])=>m.route52===id&&m.kind==='术法').map(([n])=>n)];html+=`<div class="qi-grid52">${[...new Set(titles)].map(title=>{const m=Q.library[title],b=S.state().books[title],why=acquireReason(title);return card(title,esc((m.tier||'黄')+'阶 · 炼气'+(m.stage||1)+'层篇 · '+m.desc)+'<br>'+esc(why||(b?'已收录，研习与运用请到配功页。':G.inventory[m.id]>0?'抄本在行囊，先阅读收录，再到配功页研习。':'在眼前传习者处购买 → 行囊阅读 → 功法研习。')),A('购买抄本 · '+m.price+'灵石','buy',title,!teacher()||!!b||!!why||(G.inventory[m.id]||0)>0));}).join('')}</div>`;
 if(recipeGroups[id])html+=supplies()+recipePanel(id);if(id==='array')html+=arrayPanel();if(id==='pet'||id==='puppet')html+=companionPanel();if(id==='alchemy')html+=card('使用丹药','回气丹、续脉丹、清络丹可在斗法中按实际库存使用；续脉丹也可战外疗伤。',B('战外服续脉丹','medicine','mendingPill52',!(G.inventory.mendingPill52>0)));
 page(r.name,html+B('返回路线总览','open'));}
function overview(){page('炼气修行路线与百艺',card('按经历形成修行方向','先在县城入口或道观前院接传习，取得抄本、研习与器物；每条均有入门、进阶、后期三段。可同时学习多条，不设职业选择或永久锁定。',A('配功与备招','arts')+A('演练与斗法','hub')+A('返回场景','scene'))+'<div class="qi-grid52">'+Object.entries(D.routes).map(([id,r])=>{const e=entry(id);return card(r.name,esc(r.description)+'<br>已核验 '+(e.completed+1)+'/3'+(e.active?' · 当前'+(ready(id)?'可交付':'进行中'):''),B('查看路线、获取与下一步','route',id));}).join('')+'</div>'+card('辅修的实际取舍','辅修只继承本法已有条目；炼神、藏息、养元、护持各有用途，适配不由职业标签决定。',A('查看配功与适配','arts'))+card('专项辅修抄本',Object.keys(D.library).filter(n=>D.library[n].route52==='support').map(n=>esc(n+'：'+D.library[n].desc)).join('<br>'),Object.keys(D.library).filter(n=>D.library[n].route52==='support').map(n=>A('购'+n,'buy',n,!teacher()||!!acquireReason(n)||!!S.state().books[n])).join(''))+supplies()+arrayPanel()+companionPanel());}
function homeSite(){const room=S.state().room,h=G.homes41?.places?.find(x=>x.id===G.homes41.residenceId);if(h&&G.place===h.place&&room==='h41_inner'&&XTHome41.rights(h).live)return {key:h.id,name:h.name,place:h.place,room,until:h.expires??Infinity};const p=S.state().property;if(p&&G.place===p.place&&['home','alchemy','forge'].includes(room)&&(!p.expires||p.expires>S.now()))return {key:'property_'+p.place,name:'自有/承租院落',place:p.place,room,until:p.expires||Infinity};return null;}
function homeArray(){const site=homeSite();return site?state().homeArrays?.[site.key]:null;}
function arrayPanel(){const a=activeArray(),h=homeArray();return card('阵法：固定布置与临时战阵','临时战阵一座；每处个人住处的小型固定阵另计一座。固定阵只作用在该住处，不随玩家旅行；每次供能2灵石维持30日。没有整座族宅或宗门的支配权，也不能在公用街道布阵。'+(a?'<br>临时阵：'+esc(items[a.id][0]):'')+(h?'<br>本宅固定阵：'+esc(items[h.id][0])+' · '+(h.expires>S.now()?'供能余'+(h.expires-S.now())+'日':'待维护'):'固定阵需进入可住的个人居室，或实际进入有使用权的个人院落。'),B('本宅修行 · 30日','focus','',!homeSite())+A('安全休养','rest')+B('示警巡查 · 1日','survey')+B('维护本宅阵 · 2灵石 / 30日','maintain','',!h)+B('拆回本宅阵具 · 1日','dismantle','',!h))+Object.entries(arrays).map(([id,r])=>{const fixed=['guardArray52','gatherArray52','nourishArray52','watchArray52'].includes(id);return card(items[id][0],esc(r.kind+' · '+r.desc)+'<br>持有 '+(G.inventory[id]||0)+'；'+(id==='guardArray52'?'可作临时防护战阵，也可在有使用权的住处布固定护阵，降低当地修行/休养的随机风险。':r.combat?'仅临时野外战阵，交战后或离开地区失效。':'可在个人住处固定布置；示警也可在野外临时布置。'),(r.combat||id==='watchArray52'?B('野外临时布阵 · 1日','array',id,!(G.inventory[id]>0)||!S.state().recipes.includes(id)):'')+(fixed?B('本宅固定布阵 · 1日 / 2灵石','homeArray',id,!(G.inventory[id]>0)||!homeSite()||!S.state().recipes.includes(id)):''));}).join('');}
function activeArray(){const a=state()?.array;return a&&a.place===G.place&&S.now()<a.expires?a:null;}
function companionPanel(){const d=state(),p=d.pet,u=d.puppet;return card('灵兽 · 独立一个协同位',p?'青耳灵狐 · 亲近 '+p.trust+' · 等阶 '+p.tier+' · 气血 '+p.hp+'/'+(30+p.tier*10)+' · '+(p.fedUntil>S.now()?'饱食尚余'+(p.fedUntil-S.now())+'日':'饥饿，不随战'):'尚无灵兽。先学《同息御兽篇》，到乡野或山岭采集地救助受伤幼狐，交青叶草3株、兽粮2份，花7日照料。',!p?B('照料并接纳幼狐 · 7日','rescue','',!['village','ridge'].includes(G.place)||S.state().room!=='wild'):B('喂兽粮1份','feed','',!(G.inventory.beastFood52>0))+B('训练升阶 · 7日','petTrain','',p.tier>=3)+B('养伤 · 7日 / 青叶草2株','petCare','',p.hp>=30+p.tier*10))+card('傀儡 · 独立一个协同位',u?['木甲傀儡','铁甲傀儡','灵纹傀儡'][u.tier-1]+' · 机体完好度 '+u.durability+'/100；指令消耗1灵石，磨损5点，受击另有磨损。':'须先在工坊实际制作木甲傀儡，再装配。与灵兽可同时携带，但每次协同指令占本回合操作。',!u?B('装配实物木傀 · 1日','install','',!(G.inventory.woodPuppet52>0)):B('在工坊升级 · 3日','puppetUpgrade','',u.tier>=3)+B('在工坊维修 · 2日 / 赤铁砂1份','repair','',u.durability>=100));}
function accept(id,mode){const r=D.routes[id],e=entry(id),step=e.completed+1;if(!teacher()||!r||e.active||step>2)return;if(G.realm===0&&G.layer<[1,4,8][step])return notify('本段先积累到炼气'+[1,4,8][step]+'层。');if(!level(r.minds[Math.max(0,step-1)]))return notify('先取得并研习本方向已有篇章，再接传习。');transaction(()=>{entry(id).active={step,mode:mode==='utility'?'utility':'combat',at:S.now(),sourceId:teacherId(),sourcePlace:G.place,sourceRoom:S.state().room,metrics:{hits:0,wins:0,uses:0,elements:[],utility:0},craftBefore:{...state().crafted}};addLog('接下'+r.name+'第'+(step+1)+'段传习：'+objective(id,step,mode),'mute');});render();}
function report(id){const a=entry(id).active;if(!a||!ready(id))return;if(!W.present(a.sourceId))return notify('须到'+placeName(a.sourcePlace)+'的'+(a.sourceRoom==='hall'?'道观前院':'县城入口')+'，找原经办人'+(W.get(a.sourceId)?.name||'传习者')+'当面核验。');const person=W.get(a.sourceId),item=['alchemy','forge'].includes(id)?deliveryItem(id,a.step):null,reward=item?Math.floor(items[item][1]*.9):0;if(reward>(person.wallet52??120))return notify('经办人的现有酬金不足，实物没有交付。');transaction(()=>{if(!days(1,'传习核验'))return;const e=entry(id),step=e.active.step;if(!W.present(e.active.sourceId))throw Error('经办人已不在');if(item){if(!(G.inventory[item]>0))throw Error('交付物变化');G.inventory[item]--;person.wallet52=(person.wallet52??120)-reward;person.received52||={};person.received52[item]=(person.received52[item]||0)+1;stoneChange(G,reward,'向'+person.name+'交付百艺实物');}e.completed=step;e.history.push({step,at:S.now(),sourceId:e.active.sourceId,metrics:e.active.metrics});e.active=null;addLog('向'+person.name+'交代'+D.routes[id].name+'第'+(step+1)+'段，已当面核验；后续篇章需另行购买研习。','up');});render();}
function installArray(id){if(!arrays[id]||!S.state().recipes.includes(id)||!(G.inventory[id]>0))return;if(!['wild','hunt'].includes(S.state().room)||!arrays[id].combat&&id!=='watchArray52')return notify('此阵不能在这里临时布置。攻击、困敌战阵到野外；固定辅助阵需回个人住处。');transaction(()=>{if(!days(1,'布阵'))return;G.inventory[id]--;state().array={id,place:G.place,charges:arrays[id].charges||1,expires:S.now()+30,createdAt:S.now()};addLog('在'+placeName(G.place)+'布置临时'+items[id][0]+'，离开地区后失效。','mute');});render();}
function fixedArrayAction(type,id){const site=homeSite();if(!site)return notify('须进入有使用权的个人居室或自有/承租院落。');const d=state();d.homeArrays||={};const h=d.homeArrays[site.key];if(type==='homeArray'){if(!['guardArray52','gatherArray52','nourishArray52','watchArray52'].includes(id)||!S.state().recipes.includes(id)||!(G.inventory[id]>0)||G.stones<2)return notify('固定小阵须有相应工艺、实物阵具与供能灵石2枚。');transaction(()=>{if(!days(1,'固定布阵')||!homeSite())return;G.inventory[id]--;if(h)G.inventory[h.id]=(G.inventory[h.id]||0)+1;stoneChange(G,-2,'固定阵初次供能');d.homeArrays[site.key]={id,siteKey:site.key,place:site.place,room:site.room,expires:S.now()+30,createdAt:S.now()};addLog('在'+site.name+'布置'+items[id][0]+'，仅作用于该处，离家仍保留。','mute');});}
 if(type==='maintain'&&h){if(G.stones<2)return notify('维护需要2灵石。');if(h.expires>S.now()+1)return notify('供能尚未用尽，期满后再维护，不叠加囤积。');transaction(()=>{stoneChange(G,-2,'固定阵维护');h.expires=S.now()+30;});}
 if(type==='dismantle'&&h)transaction(()=>{if(!days(1,'拆回阵具'))return;G.inventory[h.id]=(G.inventory[h.id]||0)+1;delete state().homeArrays[site.key];});render();}
function rescue(){if(!['village','ridge'].includes(G.place)||S.state().room!=='wild'||state().pet)return;if(!level('同息御兽篇')||(G.inventory.herb||0)<3||(G.inventory.beastFood52||0)<2)return notify('须研习同息御兽篇，备青叶草3株、兽粮2份。');transaction(()=>{if(!days(7,'照料幼狐'))return;G.inventory.herb-=3;G.inventory.beastFood52-=2;state().pet={id:'fox_'+G.world36.playerId,tier:1,hp:40,trust:20,fedUntil:S.now()+60};addLog('受伤幼狐恢复后愿意跟随，实际照料与用物已记录。','up');});render();}
function companionAction(type){const d=state(),p=d.pet,u=d.puppet;if(type==='feed'&&p){if(!(G.inventory.beastFood52>0))return;if(p.fedUntil>S.now()+45)return notify('灵兽目前饱足，过些时日再喂，不重复消耗兽粮。');transaction(()=>{G.inventory.beastFood52--;p.fedUntil=S.now()+60;p.trust=Math.min(100,p.trust+2);});}
 if(type==='petTrain'&&p){if(!safe()||p.tier>=3)return;const need=p.tier===1?4:8;if(G.realm===0&&G.layer<need)return notify('下一次灵兽训练需炼气'+need+'层，避免超负荷指挥。');if((G.inventory.beastFood52||0)<2||p.fedUntil<=S.now())return notify('须先喂养并另备兽粮2份。');transaction(()=>{if(!days(7,'灵兽训练'))return;G.inventory.beastFood52-=2;p.tier++;p.hp=30+p.tier*10;p.trust=Math.min(100,p.trust+5);p.fedUntil=S.now()+60;});}
 if(type==='petCare'&&p){if(!safe()||(G.inventory.herb||0)<2)return notify('回安全地点，备青叶草2株养伤。');transaction(()=>{if(!days(7,'灵兽养伤'))return;G.inventory.herb-=2;p.hp=30+p.tier*10;});}
 if(type==='install'&&!u){if(!safe()||!(G.inventory.woodPuppet52>0))return;if(!level('机枢分念篇'))return notify('先研习机枢分念篇，具备基本操持能力。');transaction(()=>{if(!days(1,'装配木傀'))return;G.inventory.woodPuppet52--;d.puppet={id:'puppet_'+G.world36.playerId,tier:1,durability:100};});}
 if(type==='puppetUpgrade'&&u){if(G.realm===0&&G.layer<(u.tier===1?4:8))return notify('本次升级需要相应中后期主持能力。');const item=u.tier===1?'puppetFrame52':'spiritCore52';if(!bench()||u.tier>=3||!(G.inventory[item]>0))return notify('到县中工坊，备齐对应机枢实物。');transaction(()=>{if(!days(3,'傀儡升级'))return;G.inventory[item]--;u.tier++;u.durability=100;});}
 if(type==='repair'&&u){if(!bench()||!(G.inventory.ironOre>0))return notify('须在工坊备赤铁砂1份。');transaction(()=>{if(!days(2,'傀儡维修'))return;G.inventory.ironOre--;u.durability=100;});}render();}
function augmentStats(s){const m=Q.library[s.mind],a=s.aux;for(const [k,n]of Object.entries(m?.battle||{})){if(k==='hp')s.maxHp+=n;if(k==='mp')s.maxMp+=n;if(k==='defense')s.defense+=n;}s.pierce52=m?.battle?.pierce||0;s.features52={};for(const type of ['element','talisman','array','pet','puppet','alchemy','forge','conceal'])s.features52[type]=(m?.bonus===type?1:0)+(a[type]||0);if(G.equipment.weapon==='edgeBlade52'){s.attack+=3;}if(G.equipment.weapon==='spiritFocus52'){s.maxMp+=6;s.attack+=1;}if(G.equipment.weapon==='ringBlade52'){s.attack+=5;s.maxMp+=3;}if(G.equipment.armor==='bodyArmor52')s.defense+=5;return s;}
const isArtifact=id=>id==='spiritBlade'||C.catalog[id]?.kind==='法器';
const isBlade=id=>['ironSword','spiritBlade','edgeBlade52','ringBlade52'].includes(id);
function beginBattle(b){const d=state(),a=activeArray();b.features52={hits:{},elements:[],shield:0,burn:0,burnTurns:0,weaken:0,weakenTurns:0,array:!b.training&&a&&arrays[a.id].combat?{...a}:null,pet:d.pet&&d.pet.hp>0&&d.pet.fedUntil>S.now()?{...d.pet}:null,puppet:d.puppet&&d.puppet.durability>0?{...d.puppet}:null};if(!b.training&&a&&arrays[a.id].combat)d.array=null;}
function available(b){const x=b.features52;if(!x)return [];const out=[];for(const [id,move]of Object.entries({firePaper52:'paperFire52',guardPaper52:'paperGuard52',bindPaper52:'paperBind52',breathPill52:'pillBreath52',mendingPill52:'pillMending52',clearPill52:'pillClear52'}))if(G.inventory[id]>0)out.push(move);if(x.pet?.hp>0)out.push('pet52');if(x.puppet?.durability>0)out.push('puppet52');if(x.array?.charges>0)out.push('array52');return out;}
function canMove(b,move){const m=D.moves[move],x=b.features52;if(m){if(!b.stats.spells.some(n=>Q.moveFor(n)===move)||m.weapon&&!isBlade(b.stats.weapon)||m.artifact&&!isArtifact(b.stats.weapon))return false;return true;}if(['pet52','puppet52','array52',...Object.keys(Q.moveDefs).filter(k=>k.startsWith('paper')||k.startsWith('pill'))].includes(move)){if(move==='puppet52'&&G.stones<1)return false;return available(b).includes(move);}if(move==='sword')return isBlade(b.stats.weapon)&&b.stats.spells.some(n=>Q.moveFor(n)===move);if(move==='control')return isArtifact(b.stats.weapon)&&b.stats.spells.some(n=>Q.moveFor(n)===move);return undefined;}
function adjustCost(b,move,value){const m=D.moves[move];if(move==='step'&&(b.stats.features52?.conceal||0)>0)value=Math.max(0,value-1);if(m?.element&&b.stats.features52?.element>0)value=Math.max(1,value-Math.min(1,b.stats.features52.element));return value;}
function hit(b,style,element){const x=b.features52;if(!x)return;x.hits[style]=(x.hits[style]||0)+1;if(element&&!x.elements.includes(element))x.elements.push(element);}
function resolveMove(b,move,act){const x=b.features52;if(!x)return null;const m=D.moves[move];x.petCommand=false;x.puppetCommand=false;b.pierce52=b.stats.pierce52||0;let damage=0,guard=0,skip=false;
 if(m){damage=b.stats.attack+m.damage+(b.stats.main===m.style?Math.round(4*b.stats.mainLevel):0)+Math.floor((b.stats.aux[m.style]||0)*3);guard=m.guard||0;skip=!!m.interrupt&&act==='蓄势';if(m.interrupt)b.charged=false;b.pierce52=(m.pierce||0)+b.stats.pierce52;if(m.weaken){x.weaken=m.weaken;x.weakenTurns=m.duration||1;}if(m.burn){x.burn=m.burn;x.burnTurns=2;}if(m.shield)x.shield=Math.min(40,x.shield+m.shield);hit(b,m.style,m.element);return {damage,guard,skip};}
 const papers={paperFire52:'firePaper52',paperGuard52:'guardPaper52',paperBind52:'bindPaper52'},pills={pillBreath52:'breathPill52',pillMending52:'mendingPill52',pillClear52:'clearPill52'};
 if(papers[move]){G.inventory[papers[move]]--;const bonus=Math.floor((b.stats.features52?.talisman||0)*4);if(move==='paperFire52'){damage=14+bonus;x.burn=3;x.burnTurns=2;}if(move==='paperGuard52')x.shield=Math.min(40,x.shield+20+bonus);if(move==='paperBind52'){damage=6+bonus;x.weaken=7;x.weakenTurns=2;b.charged=false;skip=act==='蓄势';}hit(b,'talisman');return {damage,guard,skip};}
 if(pills[move]){G.inventory[pills[move]]--;if(move==='pillBreath52')b.mp=Math.min(b.stats.maxMp,b.mp+12);else b.hp=Math.min(b.stats.maxHp,b.hp+(move==='pillMending52'?36:24));if(move==='pillClear52'){x.burn=0;x.burnTurns=0;x.weaken=0;x.weakenTurns=0;}hit(b,'alchemy');return {damage:0};}
 if(move==='pet52'){damage=5+x.pet.tier*4+Math.floor(x.pet.trust/25)+Math.floor((b.stats.features52?.pet||0)*3);x.petCommand=true;hit(b,'pet');return {damage};}
 if(move==='puppet52'){stoneChange(G,-1,'傀儡驱动');x.puppet.durability=Math.max(0,x.puppet.durability-5);damage=7+x.puppet.tier*5+Math.floor((b.stats.features52?.puppet||0)*3);x.puppetCommand=true;hit(b,'puppet');return {damage};}
 if(move==='array52'&&x.array){x.array.charges--;const bonus=Math.floor((b.stats.features52?.array||0)*3);if(x.array.id==='attackArray52'){damage=18+bonus;b.pierce52=3;}if(x.array.id==='guardArray52')x.shield=Math.min(40,x.shield+22+bonus);if(x.array.id==='trapArray52'){x.weaken=8+bonus;x.weakenTurns=2;b.charged=false;skip=act==='蓄势';}hit(b,'array');return {damage,guard,skip};}return null;
}
function afterPlayer(b,move,{guard,skip,act}){const x=b.features52;if(!x)return {};if(move==='sword')hit(b,'edge');if(move==='palm')hit(b,'body');if(move==='control')hit(b,'spirit');let add=0;if(x.burnTurns>0&&x.burn>0){b.enemy.hp=Math.max(0,b.enemy.hp-x.burn);x.burnTurns--;b.log.push('灼伤造成'+x.burn+'伤害。');}if(x.weakenTurns>0){add+=x.weaken;x.weakenTurns--;}if(x.shield>0&&act!=='蓄势'&&!skip){const raw=b.enemy.attack+(act==='重扑'?4:0)+(b.charged?6:0),absorbed=Math.min(x.shield,Math.max(0,raw-guard-add-b.stats.defense));add+=absorbed;x.shield-=absorbed;}return {guard:add};}
function afterEnemy(b,hitDamage){const x=b.features52;if(!x)return;if(x.petCommand&&x.pet){x.pet.hp=Math.max(0,x.pet.hp-Math.max(1,Math.floor(hitDamage*.3)));x.petCommand=false;}if(x.puppetCommand&&x.puppet){x.puppet.durability=Math.max(0,x.puppet.durability-Math.min(4,Math.floor(hitDamage*.2)));x.puppetCommand=false;}}
function finishBattle(b,outcome){const d=state(),x=b.features52;if(!x)return;if(!b.training){if(x.pet&&d.pet)d.pet.hp=x.pet.hp;if(x.puppet&&d.puppet)d.puppet.durability=x.puppet.durability;for(const [id,r]of Object.entries(D.routes)){const a=entry(id).active;if(!a||['alchemy','forge'].includes(id))continue;const m=a.metrics;m.hits+=x.hits[r.style]||0;for(const element of x.elements)if(id==='element'&&!m.elements.includes(element))m.elements.push(element);if(outcome==='win'&&b.target===['rat','wolf','boar'][a.step])m.wins++;}}}
function battleInfo(b){const x=b.features52;if(!x)return '';return '<p class="sb-note">护盾 '+x.shield+' · 灼伤余 '+x.burnTurns+'回合 · 缠绕余 '+x.weakenTurns+'回合'+(x.array?'<br>'+esc(items[x.array.id][0])+'：阵力余'+x.array.charges:'')+(x.pet?'<br>青耳灵狐：气血'+x.pet.hp:'')+(x.puppet?'<br>傀儡：完好度'+x.puppet.durability:'')+'<br>协同指令占本回合操作；灵兽与傀儡各有独立携带位。</p>';}
function utilityEvidence(id){const a=entry('array').active;if(a?.mode==='utility'&&['gatherArray52','nourishArray52','watchArray52'][a.step]===id){a.metrics.utility++;}}
function restWithArray(){const h=homeArray();if(!h||h.id!=='nourishArray52'||h.expires<=S.now())return false;transaction(()=>{if(!days(3,'温脉阵休养'))return;const s=Q.stats();Q.state().health={hp:s.maxHp,mp:s.maxMp};utilityEvidence(h.id);addLog('在本宅温脉阵内休养三日，气血真元恢复；长期伤势仍需按年限与丹药处理。','up');});render();return true;}
function focus(){if(!homeSite())return notify('先进入有使用权的个人居室或院落。');transaction(()=>{if(!days(30,'walk',{rate:CFG.walkRate}))return;addLog('在个人住处按实际灵气与功法修行三十日。','mute');});render();}
function survey(){const h=homeArray(),a=activeArray();if(!(h?.id==='watchArray52'&&h.expires>S.now())&&a?.id!=='watchArray52')return notify('须在本宅示警阵内，或在已布临时示警阵的野外巡查。');transaction(()=>{if(!days(1,'示警巡查'))return;if(a?.id==='watchArray52')state().array=null;addLog('核验阵眼与四周动静，示警阵参与这次实际巡查。','mute');});render();}
function useMedicine(id){if(!systemReady()||!(G.inventory[id]>0))return;const h=Q.vitals(),restoreMp=id==='breathPill52';if(restoreMp?h.mp>=h.maxMp:h.hp>=h.maxHp&&!(id==='mendingPill52'&&G.injured>0))return notify('当前不需要这份丹药，不消耗。');transaction(()=>{G.inventory[id]--;if(restoreMp)Q.state().health.mp=Math.min(h.maxMp,h.mp+12);else Q.state().health.hp=Math.min(h.maxHp,h.hp+(id==='mendingPill52'?36:24));if(id==='mendingPill52')G.injured=Math.max(0,(G.injured||0)-1);addLog('服用'+items[id][0]+'，按实际气血/真元与伤势恢复。','up');});render();}
function dispatch(a,arg){if(!a?.startsWith('q52:'))return false;if(!systemReady())return true;message='';const type=a.slice(4);if(type==='open'){V.tab='routes52';V.route52=null;render();return true;}if(type==='route'&&D.routes[arg]){V.tab='routes52';V.route52=arg;render();return true;}if(type==='supply')buySupply(arg);if(type==='craft')craft(arg);if(type==='accept'){const [id,mode]=arg.split(':');if(D.routes[id])accept(id,mode);}if(type==='report'&&D.routes[arg])report(arg);if(type==='cancel'&&D.routes[arg]&&entry(arg).active){transaction(()=>{entry(arg).history.push({step:entry(arg).active.step,at:S.now(),cancelled:true});entry(arg).active=null;addLog('放弃'+D.routes[arg].name+'本段证据，已完成段落、已学功法与实际物品保留，可另找传习者重接。','mute');});render();}if(type==='array')installArray(arg);if(type==='rescue')rescue();if(['feed','petTrain','petCare','install','repair','puppetUpgrade'].includes(type))companionAction(type);if(type==='medicine'&&arg==='mendingPill52'&&(G.inventory[arg]||0)>0){transaction(()=>{G.inventory[arg]--;G.injured=Math.max(0,(G.injured||0)-1);Q.state().health||={hp:0,mp:0};Q.state().health.hp=Math.min(Q.stats().maxHp,Q.state().health.hp+36);});render();}return true;}
const old={dispatch:S.dispatch,renderView:W.renderView,renderScene,restore,advanceDays};
S.dispatch=function(a,arg){if(a==='make'&&recipes[arg]){if(systemReady())craft(arg);return;}if(a==='use'&&['breathPill52','mendingPill52','clearPill52'].includes(arg)){useMedicine(arg);return;}if(a==='q51:rest'&&systemReady()&&restWithArray())return;if(a?.startsWith('q52:')&&['homeArray','maintain','dismantle','focus','survey'].includes(a.slice(4))){if(!systemReady())return;message='';if(a==='q52:focus')focus();else if(a==='q52:survey')survey();else fixedArrayAction(a.slice(4),arg);return;}if(dispatch(a,arg))return;return old.dispatch(a,arg);};
advanceDays=function(n,ctx={},opt={}){if(!G?.root||!state())return old.advanceDays(n,ctx,opt);const d=state();if(d.array?.place!==G.place)d.array=null;const h=homeArray(),a=activeArray(),now=S.now();let active=h&&h.expires>now?h:null;
 if(!active&&a?.id==='watchArray52'&&['寻妖','示警巡查'].includes(ctx.act))active=a;
 if(!active)return old.advanceDays(n,ctx,opt);
 const maximum=Math.min(Math.max(0,Math.floor(n)),Math.max(0,Math.min(active.expires,active===h?(homeSite()?.until??Infinity):Infinity)-now)),firstCtx={...ctx};let applied=false;
 if(active.id==='gatherArray52'&&!ctx.idle&&(ctx.rate??CFG.walkRate)>0&&['walk','retreat'].includes(ctx.act)){firstCtx.rate=(ctx.rate??CFG.walkRate)*1.10;applied=true;}
 if(['guardArray52','watchArray52'].includes(active.id)&&['walk','retreat','休养','温脉阵休养','寻妖','示警巡查'].includes(ctx.act)){firstCtx.eventRate=(ctx.eventRate??(ctx.retreat?CFG.retreatEventRate:CFG.eventRate))*(active.id==='guardArray52'?.85:.75);applied=true;}
 if(!applied||maximum<=0)return old.advanceDays(n,ctx,opt);const first=old.advanceDays(maximum,firstCtx,opt);if(first.days>0&&(active.id!=='gatherArray52'||first.gain>0)){state().utility[active.id]=(state().utility[active.id]||0)+1;utilityEvidence(active.id);if(active===a&&a?.id==='watchArray52')state().array=null;}
 if(first.days<maximum||first.died||first.broke||first.event&&opt.stopOnEvent!==false||maximum>=n)return first;const next=old.advanceDays(n-maximum,{...ctx,cost:0},opt),out={...first,...next,level0:first.level0,event:next.event||first.event};for(const k of ['days','months','years','gain','income','cost','qiPenalty'])out[k]=(first[k]||0)+(next[k]||0);for(const k of ['died','broke','full','levelUp'])out[k]=!!first[k]||!!next[k];return out;
};
const arrive=arriveAt;arriveAt=function(...args){const out=arrive(...args);if(G?.qi52?.array&&G.qi52.array.place!==G.place)G.qi52.array=null;return out;};
W.renderView=function(){if(G?.mode==='idle'&&V.tab==='routes52'&&!Q.state()?.battle){if(V.route52)routePage(V.route52);else overview();return true;}return old.renderView();};
renderScene=function(){old.renderScene();if(G?.root&&G.mode==='idle'&&!Q.state()?.battle){if(V.tab==='scene'){const p=document.querySelector('#scene .sb-place');if(p&&[teacher(),bench(),!!homeSite(),['village','ridge'].includes(G.place)&&S.state().room==='wild'].some(Boolean)){p.insertAdjacentHTML('beforeend',card('修行路线与百艺','查看实际获取、传习、制作与下一步；可混搭，不设职业锁。',B('各路修行、百艺与阵法','open')+(homeSite()?B('本宅修行 · 30日','focus')+B('示警巡查 · 1日','survey'):'')));bind(p);}}if(V.tab==='craft')for(const b of document.querySelectorAll('#scene [data-sb="make"]'))if(recipes[b.dataset.arg]){const why=craftReason(b.dataset.arg);if(why){b.disabled=true;b.parentElement.insertAdjacentHTML('beforeend','<p class="sb-note">'+esc(why)+'</p>');}}}};
const accepted=XTScene46.accepted;XTScene46.accepted=function(){const rows=accepted();if(!state())return rows;for(const [id,r]of Object.entries(D.routes)){const e=entry(id);if(e.active)rows.push({title:r.name+' · '+['入门','进阶','后期'][e.active.step],status:ready(id)?'待核验':'进行中',text:objective(id,e.active.step,e.active.mode),where:placeName(e.active.sourcePlace)+' · '+(e.active.sourceRoom==='hall'?'道观前院':'县城入口')+' · '+(W.get(e.active.sourceId)?.name||'原经办人'),next:ready(id)?'回原经办人所在地点 → 各路修行与百艺 → 对应路线 → 当面核验':objective(id,e.active.step,e.active.mode),need:'证据在本段接取后积累，演练不记实战胜利。',finish:'回原经办人处，实际交付/核验耗一日；完成记录不可重复结算。'});}return rows;};
restore=function(raw){try{const s=JSON.parse(raw),d=s.qi52;if(d){if(d.version!==1||!d.routes||!d.skills||!d.crafted||!d.utility||!d.market||d.ownerId!==s.world36?.playerId)throw Error('路线档案无效');for(const [id,e]of Object.entries(d.routes)){if(!D.routes[id]||!Number.isInteger(e.completed)||e.completed< -1||e.completed>2||!Array.isArray(e.history))throw Error('传习进度无效');if(e.active&&(!Number.isInteger(e.active.step)||e.active.step!==e.completed+1||!e.active.metrics||!Array.isArray(e.active.metrics.elements)||!e.active.craftBefore))throw Error('传习证据无效');}if(d.pet&&(![1,2,3].includes(d.pet.tier)||!Number.isFinite(d.pet.hp)||d.pet.hp<0||!Number.isFinite(d.pet.fedUntil)))throw Error('灵兽状态无效');if(d.puppet&&(![1,2,3].includes(d.puppet.tier)||!Number.isFinite(d.puppet.durability)||d.puppet.durability<0||d.puppet.durability>100))throw Error('傀儡状态无效');for(const a of [d.array,...Object.values(d.homeArrays||{})].filter(Boolean))if(!arrays[a.id]||!Number.isFinite(a.expires))throw Error('阵法状态无效');}}catch(e){XTEconomy40.lastRestoreError='路线、阵法或协同存档无效，原档保留。';return false;}return old.restore(raw);};
window.XTQi52={state,open(){V.tab='routes52';V.route52=null;render();},dispatch,acquireReason,studyReason,augmentStats,beginBattle,finishBattle,adjustCost,canMove,resolveMove,afterPlayer,afterEnemy,extraMoves:available,battleInfo,isArtifact,arrays,activeArray,homeSite,homeArray,recipes,craft,craftReason,ready,entry,utilityEvidence,items,level,deliveryItem,teacherId,onManualBought(price){const n=W.get(teacherId());if(n)n.wallet52=(n.wallet52??120)+price;},escapeGuard(b){return Math.floor((b.stats.features52?.conceal||0)*3);}};
